    <header class="header" :class="{ 'home-direct-nav': directHomeNavHidden, 'intro-root': isIntroRoot, 'initial-chrome-pending': !initialChromeReady, 'mobile-menu-surface': mobileMenuOpen || mobileMenuClosing }" v-show="!cvChromeHidden && !previewMode">
      <h3 class="header-title desktop-global-nav">
